 48→// --- Types ---
 49→
 50→interface AnswerOption {
 51→  id: string;
 52→  label: string;
 53→  score: number;
 54→  productTags: string[];
 55→  position: number;
 56→}
 57→
 58→interface Question {
 59→  id: string;
 60→  title: string;
 61→  type: string;
 62→  required: boolean;
 63→  position: number;
 64→  options: AnswerOption[];
 65→}
 66→
 67→interface DesignSettings {
 68→  quizTitle: string;
 69→  description: string;
 70→  buttonColor: string;
 71→  buttonText: string;
 72→  resultsHeading: string;
 73→  showProgressBar: boolean;
 74→}
 75→
 76→interface LoaderData {
 77→  quiz: {
 78→    id: string;
 79→    title: string;
 80→    description: string | null;
 81→    slug: string;
 82→    status: string;
 83→    settings: string;
 84→    styling: string;
 85→  };
 86→  questions: Question[];
 87→  designSettings: DesignSettings;
