 996→          type: q.type,
 997→          required: q.required,
 998→          position: qi,
 999→          options: q.options.map((o, oi) => ({
1000→            id: o.id,
1001→            label: o.label,
1002→            score: o.score,
1003→            productTags: o.productTags,
1004→            position: oi,
1005→          })),
1006→        })),
1007→      ),
1008→    );
1009→    submit(formData, { method: "POST" });
1010→  }, [questions, submit]);
1011→
1012→  // Save design tab
1013→  const handleSaveDesign = useCallback(() => {
1014→    const stylingObj = {
1015→      buttonColor: design.buttonColor,
1016→      buttonText: design.buttonText,
1017→      resultsHeading: design.resultsHeading,
1018→      showProgressBar: design.showProgressBar,
1019→    };
1020→    const formData = new FormData();
1021→    formData.set("intent", "save-design");
1022→    formData.set("title", design.quizTitle);
1023→    formData.set("description", design.description);
1024→    formData.set("styling", JSON.stringify(stylingObj));
1025→    submit(formData, { method: "POST" });
1026→  }, [design, submit]);
1027→
1028→  const handlePublish = useCallback(() => {
1029→    const formData = new FormData();
1030→    formData.set("intent", "publish");
1031→    submit(formData, { method: "POST" });
1032→  }, [submit]);
1033→
1034→  const handleUnpublish = useCallback(() => {
1035→    const formData = new FormData();
1036→    formData.set("intent", "unpublish");
1037→    submit(formData, { method: "POST" });
1038→  }, [submit]);
1039→
1040→  const handleDeleteConfirm = useCallback(() => {
