1108→      const newOptionId = `${question.id}a${Date.now()}`;
1109→      question.options = [
1110→        ...question.options,
1111→        {
1112→          id: newOptionId,
1113→          label: "",
1114→          score: 0,
1115→          productTags: [],
1116→          position: question.options.length,
1117→        },
1118→      ];
1119→      updated[selectedQuestionIndex] = question;
1120→      return updated;
1121→    });
