// =============================================================================
// Quiz Builder — 5-tab editor
// Tabs: Questions | Product Mapping | Design | Settings | Logic
// =============================================================================

import { showToast } from "../utils/toast";
import { useState, useCallback, useEffect } from "react";
import {
  data,
  redirect,
  type ActionFunctionArgs,
  type HeadersFunction,
  type LoaderFunctionArgs,
} from "react-router";
import { useLoaderData, useActionData, useNavigate, useSubmit } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Badge,
  Button,
  Box,
  Divider,
  TextField,
  Select,
  Tabs,
  Tag,
  Checkbox,
  FormLayout,
  Banner,
  EmptyState,
  Modal,
  SkeletonPage,
  SkeletonBodyText,
  RangeSlider,
} from "@shopify/polaris";
import {
  PlusIcon,
  DeleteIcon,
  DragHandleIcon,
  EyeFirstIcon,
  SaveIcon,
  XIcon,
  ProductIcon,
  ChevronDownIcon,
  ChevronUpIcon,
  CodeIcon,
  ClipboardIcon,
} from "@shopify/polaris-icons";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";

// =============================================================================
// TYPES
// =============================================================================

interface AnswerOption {
  id: string;
  text: string;
  imageUrl: string;
  score: number;
  productTags: string[];
  nextQuestionId: string;
  position: number;
}

interface QuestionSettings {
  allowMultiple?: boolean;
  min?: number;
  max?: number;
  step?: number;
  unit?: string;
  minLabel?: string;
  maxLabel?: string;
  placeholder?: string;
  maxLength?: number;
  consentText?: string;
  skipLinkText?: string;
  maxRating?: number;
  ratingStyle?: string;
}

interface LogicRule {
  answerId: string;
  goto: string;
}

interface QuestionLogic {
  rules: LogicRule[];
}

interface Question {
  id: string;
  title: string;
  description: string;
  imageUrl: string;
  type: string;
  required: boolean;
  position: number;
  settings: QuestionSettings;
  logic: QuestionLogic;
  answers: AnswerOption[];
}

interface DesignSettings {
  primaryColor: string;
  buttonTextColor: string;
  buttonText: string;
  fontFamily: string;
  borderRadius: string;
  showProgressBar: boolean;
  progressBarStyle: string;
  showQuestionCount: boolean;
  resultsHeading: string;
}

interface QuizSettings {
  requireEmail: boolean;
  emailConsentText: string;
  showProgressBar: boolean;
}

interface LoaderQuiz {
  id: string;
  title: string;
  description: string;
  slug: string;
  status: string;
  type: string;
  settings: string;
  styling: string;
}

interface LoaderData {
  quiz: LoaderQuiz;
  questions: Question[];
  designSettings: DesignSettings;
  quizSettings: QuizSettings;
}

// =============================================================================
// CONSTANTS
// =============================================================================

const QUESTION_TYPES = [
  { label: "Single choice", value: "multiple-choice", hasAnswers: true },
  { label: "Image choice", value: "image-choice", hasAnswers: true },
  { label: "Dropdown", value: "dropdown", hasAnswers: true },
  { label: "Slider", value: "slider", hasAnswers: false },
  { label: "Text input", value: "text-input", hasAnswers: false },
  { label: "Email capture", value: "email", hasAnswers: false },
  { label: "Rating", value: "rating", hasAnswers: false },
] as const;

type QuestionTypeValue = (typeof QUESTION_TYPES)[number]["value"];

const QUESTION_TYPE_OPTIONS = QUESTION_TYPES.map((t) => ({
  label: t.label,
  value: t.value,
}));

const FONT_OPTIONS = [
  { label: "System default", value: "system" },
  { label: "Inter", value: "Inter" },
  { label: "Poppins", value: "Poppins" },
  { label: "Playfair Display", value: "Playfair Display" },
  { label: "Roboto", value: "Roboto" },
];

const BORDER_RADIUS_OPTIONS = [
  { label: "Sharp (0px)", value: "0" },
  { label: "Rounded (8px)", value: "8" },
  { label: "Pill (24px)", value: "24" },
];

const PROGRESS_STYLE_OPTIONS = [
  { label: "Bar", value: "bar" },
  { label: "Steps", value: "steps" },
  { label: "Percentage", value: "percentage" },
];

const QUIZ_TYPE_OPTIONS = [
  { label: "Product Recommendation", value: "product-recommendation" },
  { label: "Personality", value: "personality" },
  { label: "Assessment", value: "assessment" },
  { label: "Survey", value: "survey" },
  { label: "Lead Generation", value: "lead-gen" },
];

const MAX_RATING_OPTIONS = [
  { label: "3", value: "3" },
  { label: "4", value: "4" },
  { label: "5", value: "5" },
  { label: "7", value: "7" },
  { label: "10", value: "10" },
];

const RATING_STYLE_OPTIONS = [
  { label: "Stars", value: "stars" },
  { label: "Numbers", value: "numbers" },
  { label: "Hearts", value: "hearts" },
];

function getTypeLabel(type: string): string {
  return QUESTION_TYPES.find((t) => t.value === type)?.label ?? type;
}

function typeHasAnswers(type: string): boolean {
  return (
    QUESTION_TYPES.find((t) => t.value === type)?.hasAnswers ?? false
  );
}

function parseSafe<T>(str: string, fallback: T): T {
  try {
    return JSON.parse(str) as T;
  } catch {
    return fallback;
  }
}

function makeNewAnswer(position: number, questionId: string): AnswerOption {
  return {
    id: `new-${questionId}-ans-${Date.now()}-${position}`,
    text: "",
    imageUrl: "",
    score: 0,
    productTags: [],
    nextQuestionId: "",
    position,
  };
}

function makeNewQuestion(position: number): Question {
  const id = `new-q-${Date.now()}-${position}`;
  return {
    id,
    title: "",
    description: "",
    imageUrl: "",
    type: "multiple-choice",
    required: true,
    position,
    settings: { allowMultiple: false },
    logic: { rules: [] },
    answers: [
      makeNewAnswer(0, id),
      makeNewAnswer(1, id),
    ],
  };
}

// =============================================================================
// LOADER
// =============================================================================

export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id;

  if (!quizId) {
    throw data({ error: "Missing quiz ID" }, { status: 400 });
  }

  try {
    const quiz = await db.quiz.findFirst({
      where: { id: quizId, shop: session.shop },
      include: {
        questions: {
          include: { answers: { orderBy: { position: "asc" } } },
          orderBy: { position: "asc" },
        },
        resultPages: { orderBy: { position: "asc" } },
      },
    });

    if (!quiz) {
      throw data({ error: "Quiz not found" }, { status: 404 });
    }

    const stylingObj = parseSafe<{
      primaryColor?: string;
      buttonTextColor?: string;
      buttonText?: string;
      fontFamily?: string;
      borderRadius?: string;
      showProgressBar?: boolean;
      progressBarStyle?: string;
      showQuestionCount?: boolean;
      resultsHeading?: string;
    }>(quiz.styling, {});

    const settingsObj = parseSafe<{
      requireEmail?: boolean;
      emailConsentText?: string;
      showProgressBar?: boolean;
    }>(quiz.settings, {});

    const designSettings: DesignSettings = {
      primaryColor: stylingObj.primaryColor ?? "#5C6AC4",
      buttonTextColor: stylingObj.buttonTextColor ?? "#FFFFFF",
      buttonText: stylingObj.buttonText ?? "Next",
      fontFamily: stylingObj.fontFamily ?? "system",
      borderRadius: stylingObj.borderRadius ?? "8",
      showProgressBar: stylingObj.showProgressBar ?? true,
      progressBarStyle: stylingObj.progressBarStyle ?? "bar",
      showQuestionCount: stylingObj.showQuestionCount ?? false,
      resultsHeading: stylingObj.resultsHeading ?? "Your Results",
    };

    const quizSettings: QuizSettings = {
      requireEmail: settingsObj.requireEmail ?? false,
      emailConsentText:
        settingsObj.emailConsentText ??
        "I agree to receive marketing emails.",
      showProgressBar: settingsObj.showProgressBar ?? true,
    };

    const questions: Question[] = quiz.questions.map((q) => ({
      id: q.id,
      title: q.title,
      description: q.description ?? "",
      imageUrl: q.imageUrl ?? "",
      type: q.type,
      required: q.required,
      position: q.position,
      settings: parseSafe<QuestionSettings>(q.settings, {}),
      logic: parseSafe<QuestionLogic>(q.logic, { rules: [] }),
      answers: q.answers.map((a) => ({
        id: a.id,
        text: a.text,
        imageUrl: a.imageUrl ?? "",
        score: a.score,
        productTags: parseSafe<string[]>(a.productTags, []),
        nextQuestionId: a.nextQuestionId ?? "",
        position: a.position,
      })),
    }));

    return {
      quiz: {
        id: quiz.id,
        title: quiz.title,
        description: quiz.description ?? "",
        slug: quiz.slug,
        status: quiz.status,
        type: quiz.type,
        settings: quiz.settings,
        styling: quiz.styling,
      },
      questions,
      designSettings,
      quizSettings,
    } as LoaderData;
  } catch (error) {
    if (error instanceof Response) throw error;
    throw data({ error: "Failed to load quiz" }, { status: 500 });
  }
};

// =============================================================================
// ACTION
// =============================================================================

export const action = async ({ request, params }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id!;
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");

  try {
    const quiz = await db.quiz.findFirst({
      where: { id: quizId, shop: session.shop },
    });
    if (!quiz) {
      return data({ error: "Quiz not found" }, { status: 404 });
    }

    switch (intent) {
      // ── Save questions (nuclear pattern: delete all, re-create) ──────────
      case "save-questions": {
        const questionsJson = String(formData.get("questions") ?? "[]");
        let incoming: Array<{
          id?: string;
          title: string;
          description: string;
          imageUrl: string;
          type: string;
          required: boolean;
          position: number;
          settings: QuestionSettings;
          logic: QuestionLogic;
          answers: Array<{
            text: string;
            imageUrl: string;
            score: number;
            productTags: string[];
            nextQuestionId: string;
            position: number;
          }>;
        }>;

        try {
          incoming = JSON.parse(questionsJson);
        } catch {
          return data({ error: "Invalid questions data" }, { status: 400 });
        }

        await db.question.deleteMany({ where: { quizId } });

        for (const q of incoming) {
          await db.question.create({
            data: {
              quizId,
              title: q.title || "Untitled question",
              description: q.description || null,
              imageUrl: q.imageUrl || null,
              type: q.type,
              required: q.required,
              position: q.position,
              settings: JSON.stringify(q.settings ?? {}),
              logic: JSON.stringify(q.logic ?? { rules: [] }),
              answers: {
                create: q.answers.map((a) => ({
                  text: a.text || "Option",
                  imageUrl: a.imageUrl || null,
                  score: a.score,
                  productTags: JSON.stringify(a.productTags ?? []),
                  nextQuestionId: a.nextQuestionId || null,
                  position: a.position,
                })),
              },
            },
          });
        }

        return { success: true, message: "Questions saved!" };
      }

      // ── Save design ──────────────────────────────────────────────────────
      case "save-design": {
        const title = String(formData.get("title") ?? "").trim();
        const description =
          String(formData.get("description") ?? "").trim() || null;
        const styling = String(formData.get("styling") ?? "{}");

        if (!title) {
          return data({ error: "Quiz title is required" }, { status: 400 });
        }

        await db.quiz.update({
          where: { id: quizId },
          data: { title, description, styling, updatedAt: new Date() },
        });

        return { success: true, message: "Design saved!" };
      }

      // ── Save settings ────────────────────────────────────────────────────
      case "save-settings": {
        const title = String(formData.get("title") ?? "").trim();
        const description =
          String(formData.get("description") ?? "").trim() || null;
        const slug = String(formData.get("slug") ?? "").trim();
        const type = String(formData.get("type") ?? "product-recommendation");
        const settingsJson = String(formData.get("settings") ?? "{}");

        if (!title) {
          return data({ error: "Quiz title is required" }, { status: 400 });
        }

        if (!slug || !/^[a-z0-9-]+$/.test(slug)) {
          return data(
            { error: "Slug must contain only lowercase letters, numbers, and hyphens" },
            { status: 400 },
          );
        }

        // Validate slug uniqueness (excluding this quiz)
        const existing = await db.quiz.findFirst({
          where: { shop: session.shop, slug, id: { not: quizId } },
        });
        if (existing) {
          return data(
            { error: "This slug is already used by another quiz" },
            { status: 400 },
          );
        }

        await db.quiz.update({
          where: { id: quizId },
          data: {
            title,
            description,
            slug,
            type,
            settings: settingsJson,
            updatedAt: new Date(),
          },
        });

        return { success: true, message: "Settings saved!" };
      }

      // ── Save logic ───────────────────────────────────────────────────────
      case "save-logic": {
        const logicJson = String(formData.get("logic") ?? "{}");
        let logicMap: Record<string, QuestionLogic>;

        try {
          logicMap = JSON.parse(logicJson);
        } catch {
          return data({ error: "Invalid logic data" }, { status: 400 });
        }

        for (const [questionId, logicData] of Object.entries(logicMap)) {
          await db.question.updateMany({
            where: { id: questionId, quizId },
            data: { logic: JSON.stringify(logicData) },
          });
        }

        return { success: true, message: "Logic rules saved!" };
      }

      // ── Publish ──────────────────────────────────────────────────────────
      case "publish": {
        await db.quiz.update({
          where: { id: quizId },
          data: {
            status: "active",
            publishedAt: quiz.publishedAt ?? new Date(),
          },
        });
        return {
          success: true,
          message: "Quiz published! It is now live on your storefront.",
        };
      }

      // ── Unpublish ────────────────────────────────────────────────────────
      case "unpublish": {
        await db.quiz.update({
          where: { id: quizId },
          data: { status: "draft" },
        });
        return { success: true, message: "Quiz unpublished." };
      }

      // ── Delete ───────────────────────────────────────────────────────────
      case "delete": {
        await db.quiz.delete({ where: { id: quizId } });
        return redirect("/app/quizzes");
      }

      default:
        return data({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    if (error instanceof Response) throw error;
    console.error(`Quiz action "${intent}" failed:`, error);
    return data({ error: "Action failed. Please try again." }, { status: 500 });
  }
};

// =============================================================================
// SKELETON — shown during initial hydration
// =============================================================================

export function HydrateFallback() {
  return (
    <SkeletonPage primaryAction backAction>
      <Layout>
        <Layout.Section>
          <Card>
            <SkeletonBodyText lines={8} />
          </Card>
        </Layout.Section>
        <Layout.Section variant="oneThird">
          <Card>
            <SkeletonBodyText lines={5} />
          </Card>
        </Layout.Section>
      </Layout>
    </SkeletonPage>
  );
}

// =============================================================================
// TAB 1: QUESTIONS
// =============================================================================

// --- Type-specific editors ---

function SliderEditor({
  settings,
  onChange,
}: {
  settings: QuestionSettings;
  onChange: (s: QuestionSettings) => void;
}) {
  return (
    <BlockStack gap="300">
      <Text as="h3" variant="headingSm" fontWeight="semibold">
        Slider settings
      </Text>
      <FormLayout>
        <FormLayout.Group>
          <TextField
            label="Min value"
            type="number"
            value={String(settings.min ?? 1)}
            onChange={(v) => onChange({ ...settings, min: Number(v) })}
            autoComplete="off"
          />
          <TextField
            label="Max value"
            type="number"
            value={String(settings.max ?? 10)}
            onChange={(v) => onChange({ ...settings, max: Number(v) })}
            autoComplete="off"
          />
          <TextField
            label="Step"
            type="number"
            value={String(settings.step ?? 1)}
            onChange={(v) => onChange({ ...settings, step: Number(v) })}
            autoComplete="off"
          />
        </FormLayout.Group>
        <TextField
          label="Unit label"
          value={settings.unit ?? ""}
          onChange={(v) => onChange({ ...settings, unit: v })}
          autoComplete="off"
          placeholder="e.g. minutes, days, kg"
          helpText="Shown after the slider value."
