// --- Answer options editor (for multiple-choice, image-choice, dropdown) ---

function AnswerOptionsEditor({
  question,
  onUpdateAnswer,
  onAddAnswer,
  onDeleteAnswer,
  onUpdateAnswerTags,
}: {
  question: Question;
  onUpdateAnswer: (answerId: string, field: keyof AnswerOption, value: string | number | string[]) => void;
  onAddAnswer: () => void;
  onDeleteAnswer: (answerId: string) => void;
  onUpdateAnswerTags: (answerId: string, tags: string[]) => void;
}) {
  const [tagInputs, setTagInputs] = useState<Record<string, string>>({});
  const showImageField = question.type === "image-choice";

  return (
    <BlockStack gap="300">
      <InlineStack align="space-between" blockAlign="center">
        <Text as="h3" variant="headingSm" fontWeight="semibold">
          Answer options
        </Text>
        <Badge>{String(question.answers.length)}</Badge>
      </InlineStack>

      {question.type === "multiple-choice" && (
        <Checkbox
          label="Allow multiple selections"
          helpText="Shoppers can select more than one answer."
          checked={question.settings.allowMultiple ?? false}
          onChange={(v) => {
            // This is handled by the parent through onUpdateSettings pattern,
            // but we keep it scoped here via a direct update trigger
          }}
        />
      )}

      {question.type === "dropdown" && (
        <Banner tone="info">
          <Text as="p" variant="bodySm">
            Options will appear in a dropdown menu on the storefront.
          </Text>
        </Banner>
      )}

      {question.answers.length === 0 ? (
        <Banner tone="warning">
          <Text as="p" variant="bodySm">
            Add at least one answer option for this question.
          </Text>
        </Banner>
      ) : (
        <BlockStack gap="300">
          {question.answers.map((answer, idx) => (
            <Box
              key={answer.id}
              background="bg-surface-secondary"
              borderRadius="200"
              borderWidth="025"
              borderColor="border"
              padding="300"
            >
              <BlockStack gap="200">
                <InlineStack gap="200" blockAlign="center">
                  <Text as="span" variant="bodySm" tone="subdued">
                    {idx + 1}.
                  </Text>
                  <Box style={{ flex: 1 }}>
                    <TextField
                      label={`Option ${idx + 1} label`}
                      labelHidden
                      value={answer.text}
                      onChange={(v) => onUpdateAnswer(answer.id, "text", v)}
                      autoComplete="off"
                      placeholder={`Answer option ${idx + 1}`}
                    />
                  </Box>
                  <Box style={{ width: 72 }}>
                    <TextField
                      label="Score"
                      labelHidden
                      type="number"
                      value={String(answer.score)}
                      onChange={(v) =>
                        onUpdateAnswer(answer.id, "score", Number(v))
                      }
                      autoComplete="off"
                      placeholder="0"
                    />
                  </Box>
                  <Button
                    icon={XIcon}
                    tone="critical"
                    variant="plain"
                    onClick={() => onDeleteAnswer(answer.id)}
                    accessibilityLabel={`Delete option ${idx + 1}`}
                  />
                </InlineStack>

                {showImageField && (
                  <TextField
                    label="Image URL"
                    value={answer.imageUrl}
                    onChange={(v) => onUpdateAnswer(answer.id, "imageUrl", v)}
                    autoComplete="off"
                    placeholder="https://cdn.shopify.com/..."
                    helpText="Direct URL to the answer image."
                  />
                )}

                {/* Product tags for this answer */}
                <BlockStack gap="100">
                  <Text as="p" variant="bodySm" tone="subdued">
                    Product tags
                  </Text>
                  {answer.productTags.length > 0 && (
                    <InlineStack gap="100" wrap>
                      {answer.productTags.map((tag) => (
                        <Tag
                          key={tag}
                          onRemove={() =>
                            onUpdateAnswerTags(
                              answer.id,
                              answer.productTags.filter((t) => t !== tag),
                            )
                          }
                        >
                          {tag}
                        </Tag>
                      ))}
                    </InlineStack>
                  )}
                  <InlineStack gap="100" blockAlign="end">
                    <Box style={{ flex: 1 }}>
                      <TextField
                        label="Add tag"
                        labelHidden
                        value={tagInputs[answer.id] ?? ""}
                        onChange={(v) =>
                          setTagInputs((prev) => ({
                            ...prev,
                            [answer.id]: v,
                          }))
                        }
                        autoComplete="off"
                        placeholder="e.g. sensitive-skin"
                      />
                    </Box>
                    <Button
                      size="slim"
                      onClick={() => {
                        const val = (tagInputs[answer.id] ?? "").trim();
                        if (val && !answer.productTags.includes(val)) {
                          onUpdateAnswerTags(answer.id, [
                            ...answer.productTags,
                            val,
                          ]);
                          setTagInputs((prev) => ({
                            ...prev,
                            [answer.id]: "",
                          }));
                        }
                      }}
                    >
                      Add
                    </Button>
                  </InlineStack>
                </BlockStack>
              </BlockStack>
            </Box>
          ))}
        </BlockStack>
      )}

      <Box>
        <Button icon={PlusIcon} onClick={onAddAnswer} variant="plain">
          Add answer option
        </Button>
      </Box>
    </BlockStack>
  );
}

// --- Question editor panel (right side) ---

function QuestionEditorPanel({
  question,
  questionIndex,
  allQuestions,
  onUpdateField,
  onUpdateSettings,
  onUpdateAnswer,
  onAddAnswer,
  onDeleteAnswer,
  onUpdateAnswerTags,
  onDeleteQuestion,
}: {
  question: Question;
  questionIndex: number;
  allQuestions: Question[];
  onUpdateField: (field: keyof Question, value: string | boolean | QuestionSettings | QuestionLogic) => void;
  onUpdateSettings: (settings: QuestionSettings) => void;
  onUpdateAnswer: (answerId: string, field: keyof AnswerOption, value: string | number | string[]) => void;
  onAddAnswer: () => void;
  onDeleteAnswer: (answerId: string) => void;
  onUpdateAnswerTags: (answerId: string, tags: string[]) => void;
  onDeleteQuestion: () => void;
}) {
  const hasAnswers = typeHasAnswers(question.type);

  return (
    <Card>
      <BlockStack gap="400">
        {/* Header */}
        <InlineStack align="space-between" blockAlign="center">
          <InlineStack gap="200" blockAlign="center">
            <Text as="h3" variant="headingSm" fontWeight="semibold">
              Question {questionIndex + 1}
            </Text>
            <Badge tone="info">{getTypeLabel(question.type)}</Badge>
          </InlineStack>
          <Button
            icon={DeleteIcon}
            tone="critical"
            variant="plain"
            onClick={onDeleteQuestion}
            accessibilityLabel="Delete this question"
          >
            Delete
          </Button>
        </InlineStack>

        <Divider />

        {/* Common fields */}
        <FormLayout>
          <TextField
            label="Question title"
            value={question.title}
            onChange={(v) => onUpdateField("title", v)}
            autoComplete="off"
            helpText="The main question text shoppers will read."
          />
          <TextField
            label="Description"
            value={question.description}
            onChange={(v) => onUpdateField("description", v)}
            autoComplete="off"
            multiline={2}
            placeholder="Optional helper text below the question title."
            helpText="Optional — shown as smaller text below the question."
          />
          <Select
            label="Question type"
            options={QUESTION_TYPE_OPTIONS}
            value={question.type}
            onChange={(v) => onUpdateField("type", v)}
            helpText="Changing the type keeps existing answers but adjusts the editor view."
          />
          <Checkbox
            label="Required"
            helpText="Shoppers must answer before proceeding."
            checked={question.required}
            onChange={(v) => onUpdateField("required", v)}
          />
        </FormLayout>

        <Divider />

        {/* Type-specific section */}
        {hasAnswers ? (
          <AnswerOptionsEditor
            question={question}
            onUpdateAnswer={onUpdateAnswer}
            onAddAnswer={onAddAnswer}
            onDeleteAnswer={onDeleteAnswer}
            onUpdateAnswerTags={onUpdateAnswerTags}
          />
        ) : (
          <>
            {question.type === "slider" && (
              <SliderEditor
                settings={question.settings}
                onChange={onUpdateSettings}
              />
            )}
            {question.type === "email" && (
              <EmailEditor
                settings={question.settings}
                onChange={onUpdateSettings}
              />
            )}
            {question.type === "text-input" && (
              <TextInputEditor
                settings={question.settings}
                onChange={onUpdateSettings}
              />
            )}
            {question.type === "rating" && (
              <RatingEditor
                settings={question.settings}
                onChange={onUpdateSettings}
              />
            )}
          </>
        )}
      </BlockStack>
    </Card>
  );
}

// --- Questions Tab ---

function QuestionsTab({
  questions,
  selectedQuestionIndex,
  onSelectQuestion,
  onUpdateField,
  onUpdateSettings,
  onUpdateAnswer,
  onAddAnswer,
  onDeleteAnswer,
  onUpdateAnswerTags,
  onAddQuestion,
  onDeleteQuestion,
}: {
  questions: Question[];
  selectedQuestionIndex: number;
  onSelectQuestion: (index: number) => void;
  onUpdateField: (field: keyof Question, value: string | boolean | QuestionSettings | QuestionLogic) => void;
  onUpdateSettings: (settings: QuestionSettings) => void;
  onUpdateAnswer: (answerId: string, field: keyof AnswerOption, value: string | number | string[]) => void;
  onAddAnswer: () => void;
  onDeleteAnswer: (answerId: string) => void;
  onUpdateAnswerTags: (answerId: string, tags: string[]) => void;
  onAddQuestion: () => void;
  onDeleteQuestion: (index: number) => void;
}) {
  const [addMenuOpen, setAddMenuOpen] = useState(false);
  const selectedQuestion = questions[selectedQuestionIndex];

  return (
    <Layout>
      {/* Left sidebar — question list */}
      <Layout.Section variant="oneThird">
        <BlockStack gap="300">
          <InlineStack align="space-between" blockAlign="center">
            <Text as="h3" variant="headingSm" fontWeight="semibold">
              Questions
            </Text>
            <Badge tone="info">{String(questions.length)}</Badge>
          </InlineStack>

          {questions.length === 0 ? (
            <Box
              background="bg-surface-secondary"
              borderRadius="200"
              padding="400"
            >
              <BlockStack gap="200">
                <Text
                  as="p"
                  variant="bodySm"
                  tone="subdued"
                  alignment="center"
                >
                  No questions yet. Add your first question to get started.
                </Text>
              </BlockStack>
            </Box>
          ) : (
            <BlockStack gap="100">
              {questions.map((q, index) => {
                const isSelected = index === selectedQuestionIndex;
                return (
                  <Box
                    key={q.id}
                    background={
                      isSelected ? "bg-surface-selected" : "bg-surface"
                    }
                    borderWidth="025"
                    borderColor={isSelected ? "border-focus" : "border"}
                    borderRadius="200"
                    padding="300"
                  >
                    <div
                      role="button"
                      tabIndex={0}
                      style={{ cursor: "pointer" }}
                      onClick={() => onSelectQuestion(index)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" || e.key === " ") {
                          e.preventDefault();
                          onSelectQuestion(index);
                        }
                      }}
                    >
                      <InlineStack gap="200" blockAlign="center">
                        <Box>
                          <DragHandleIcon
                            aria-label="Drag handle"
                            style={{
                              width: 16,
                              height: 16,
                              color: "var(--p-color-icon-subdued)",
                            }}
                          />
                        </Box>
                        <Box
                          background="bg-fill-info"
                          borderRadius="full"
                          minWidth="22px"
                          minHeight="22px"
                        >
                          <Box padding="050">
                            <Text
                              as="span"
                              variant="bodySm"
                              fontWeight="semibold"
                              tone="text-inverse"
                            >
                              {index + 1}
                            </Text>
                          </Box>
                        </Box>
                        <BlockStack gap="025">
                          <Text
                            as="p"
                            variant="bodySm"
                            fontWeight={isSelected ? "semibold" : "regular"}
                            truncate
                          >
                            {q.title || "Untitled question"}
                          </Text>
                          <Badge tone="info" size="small">
                            {getTypeLabel(q.type)}
                          </Badge>
                        </BlockStack>
                      </InlineStack>
                    </div>
                  </Box>
                );
              })}
            </BlockStack>
          )}

          {/* Add question controls */}
          <BlockStack gap="100">
            <Button
              icon={PlusIcon}
              onClick={onAddQuestion}
              fullWidth
              variant="primary"
            >
              Add question
            </Button>
            <Button
              onClick={() => setAddMenuOpen((v) => !v)}
              fullWidth
              variant="plain"
              icon={addMenuOpen ? ChevronUpIcon : ChevronDownIcon}
              accessibilityLabel="Choose question type to add"
            >
              Choose type
            </Button>
            {addMenuOpen && (
              <Box
                background="bg-surface"
                borderWidth="025"
                borderColor="border"
                borderRadius="200"
                padding="200"
              >
                <BlockStack gap="050">
                  {QUESTION_TYPES.map((type) => (
                    <Button
                      key={type.value}
                      variant="plain"
                      onClick={() => {
                        const id = `new-q-${Date.now()}`;
                        const newQuestion: Question = {
                          id,
                          title: "",
                          description: "",
                          imageUrl: "",
                          type: type.value,
                          required: true,
                          position: questions.length,
                          settings: {},
                          logic: { rules: [] },
                          answers: type.hasAnswers
                            ? [
                                makeNewAnswer(0, id),
                                makeNewAnswer(1, id),
                              ]
                            : [],
                        };
                        onAddQuestion();
                        setAddMenuOpen(false);
                      }}
                    >
                      {type.label}
                    </Button>
                  ))}
                </BlockStack>
              </Box>
            )}
          </BlockStack>
        </BlockStack>
      </Layout.Section>

      {/* Right panel — question editor */}
      <Layout.Section>
        {selectedQuestion ? (
          <QuestionEditorPanel
            question={selectedQuestion}
            questionIndex={selectedQuestionIndex}
            allQuestions={questions}
            onUpdateField={onUpdateField}
            onUpdateSettings={onUpdateSettings}
            onUpdateAnswer={onUpdateAnswer}
            onAddAnswer={onAddAnswer}
            onDeleteAnswer={onDeleteAnswer}
            onUpdateAnswerTags={onUpdateAnswerTags}
            onDeleteQuestion={() => onDeleteQuestion(selectedQuestionIndex)}
          />
        ) : (
          <Card>
            <EmptyState
              heading="Select a question to edit"
              image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
              action={{ content: "Add question", onAction: onAddQuestion }}
            >
              <Text as="p" variant="bodyMd" tone="subdued">
                Choose a question from the sidebar, or add a new one to get
                started.
              </Text>
            </EmptyState>
          </Card>
        )}
      </Layout.Section>
    </Layout>
  );
}

// =============================================================================
// TAB 2: PRODUCT MAPPING
// =============================================================================

function ProductMappingTab({
  questions,
  onAddTag,
  onRemoveTag,
}: {
  questions: Question[];
  onAddTag: (questionId: string, answerId: string, tag: string) => void;
  onRemoveTag: (questionId: string, answerId: string, tag: string) => void;
}) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [tagInputs, setTagInputs] = useState<Record<string, string>>({});

  const questionsWithAnswers = questions.filter((q) => typeHasAnswers(q.type));

  if (questionsWithAnswers.length === 0) {
    return (
      <EmptyState
        heading="No questions with answer options"
        image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
      >
        <Text as="p" variant="bodyMd" tone="subdued">
          Add questions with choice or dropdown answer options first, then map
          Shopify product tags to each answer.
        </Text>
      </EmptyState>
    );
  }

  return (
    <BlockStack gap="400">
      <Banner tone="info">
        <Text as="p" variant="bodyMd">
          Map Shopify product tags to each answer option. When a shopper selects
          an answer, products with matching tags will be recommended on the
          results page.
        </Text>
      </Banner>

      {questionsWithAnswers.map((question, qi) => {
        const isExpanded = expanded[question.id] !== false;
        return (
          <Card key={question.id}>
            <BlockStack gap="300">
              {/* Section header with toggle */}
              <div
                role="button"
                tabIndex={0}
                style={{ cursor: "pointer" }}
                onClick={() =>
                  setExpanded((prev) => ({
                    ...prev,
                    [question.id]: !isExpanded,
                  }))
                }
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    setExpanded((prev) => ({
                      ...prev,
                      [question.id]: !isExpanded,
                    }));
                  }
                }}
              >
                <InlineStack align="space-between" blockAlign="center">
                  <InlineStack gap="200" blockAlign="center">
                    <ProductIcon
                      aria-label="Product"
                      style={{
                        width: 18,
                        height: 18,
                        color: "var(--p-color-icon-subdued)",
                      }}
                    />
                    <Text as="h3" variant="headingSm" fontWeight="semibold">
                      Q{qi + 1}. {question.title || "Untitled question"}
                    </Text>
                  </InlineStack>
                  <InlineStack gap="200" blockAlign="center">
                    <Badge>{String(question.answers.length)} options</Badge>
                    <Button
                      variant="plain"
                      icon={isExpanded ? ChevronUpIcon : ChevronDownIcon}
                      accessibilityLabel={
                        isExpanded ? "Collapse" : "Expand"
                      }
                    />
                  </InlineStack>
                </InlineStack>
              </div>

              {isExpanded && (
                <>
                  <Divider />
                  {question.answers.length === 0 ? (
                    <Text as="p" variant="bodySm" tone="subdued">
                      No answer options. Add options in the Questions tab.
                    </Text>
                  ) : (
                    <BlockStack gap="300">
                      {question.answers.map((answer) => {
                        const inputKey = `${question.id}-${answer.id}`;
                        return (
                          <Box
                            key={answer.id}
                            background="bg-surface-secondary"
                            borderRadius="200"
                            padding="300"
                          >
                            <BlockStack gap="200">
                              <InlineStack
                                align="space-between"
                                blockAlign="center"
                              >
                                <Text
                                  as="p"
                                  variant="bodyMd"
                                  fontWeight="semibold"
                                >
                                  {answer.text || "Untitled option"}
                                </Text>
                                <Badge tone="info">
                                  Score: {answer.score}
                                </Badge>
                              </InlineStack>

                              {answer.productTags.length > 0 && (
                                <InlineStack gap="100" wrap>
                                  {answer.productTags.map((tag) => (
                                    <Tag
                                      key={tag}
                                      onRemove={() =>
                                        onRemoveTag(
                                          question.id,
                                          answer.id,
                                          tag,
                                        )
                                      }
                                    >
                                      {tag}
                                    </Tag>
                                  ))}
                                </InlineStack>
                              )}

                              <InlineStack gap="100" blockAlign="end">
                                <Box style={{ flex: 1 }}>
                                  <TextField
                                    label="Add product tag"
                                    labelHidden
                                    value={tagInputs[inputKey] ?? ""}
                                    onChange={(v) =>
                                      setTagInputs((prev) => ({
                                        ...prev,
                                        [inputKey]: v,
                                      }))
                                    }
                                    autoComplete="off"
                                    placeholder="e.g. sensitive-skin"
                                    helpText="Enter a Shopify product tag to map products to this answer."
                                  />
                                </Box>
                                <Button
                                  size="slim"
                                  onClick={() => {
                                    const val = (
                                      tagInputs[inputKey] ?? ""
                                    ).trim();
                                    if (
                                      val &&
                                      !answer.productTags.includes(val)
                                    ) {
                                      onAddTag(question.id, answer.id, val);
                                      setTagInputs((prev) => ({
                                        ...prev,
                                        [inputKey]: "",
                                      }));
                                    }
                                  }}
                                >
                                  Add tag
                                </Button>
                              </InlineStack>
                            </BlockStack>
                          </Box>
                        );
                      })}
                    </BlockStack>
                  )}
                </>
              )}
            </BlockStack>
          </Card>
        );
      })}
    </BlockStack>
  );
}

