function LogicTab({
  questions,
  onUpdateLogic,
}: {
  questions: Question[];
  onUpdateLogic: (questionId: string, logic: QuestionLogic) => void;
}) {
  const questionsWithAnswers = questions.filter((q) => typeHasAnswers(q.type));

  if (questionsWithAnswers.length === 0) {
    return (
      <BlockStack gap="400">
        <Banner tone="info">
          <Text as="p" variant="bodyMd">
            Set up conditional logic to create personalized quiz paths. Questions
            without rules follow the default sequential order.
          </Text>
        </Banner>
        <EmptyState
          heading="No questions with branching options"
          image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
        >
          <Text as="p" variant="bodyMd" tone="subdued">
            Logic rules are only available for questions with answer options
            (Single choice, Image choice, Dropdown). Add those question types
            first.
          </Text>
        </EmptyState>
      </BlockStack>
    );
  }

  // Build "go to" options: all questions + "Results page"
  const gotoOptions = [
    { label: "Results page", value: "results" },
    ...questions.map((q, idx) => ({
      label: `Q${idx + 1}: ${q.title || "Untitled question"}`,
      value: q.id,
    })),
  ];

  return (
    <BlockStack gap="400">
      <Banner tone="info">
        <Text as="p" variant="bodyMd">
          Set up conditional logic to create personalized quiz paths. Questions
          without rules follow the default sequential order.
        </Text>
      </Banner>

      {questionsWithAnswers.map((question) => {
        const qIndex = questions.findIndex((q) => q.id === question.id);

        const handleAddRule = () => {
          const firstAnswerId = question.answers[0]?.id ?? "";
          const newRules = [
            ...question.logic.rules,
            { answerId: firstAnswerId, goto: "results" },
          ];
          onUpdateLogic(question.id, { rules: newRules });
        };

        const handleDeleteRule = (ruleIndex: number) => {
          const newRules = question.logic.rules.filter(
            (_, i) => i !== ruleIndex,
          );
          onUpdateLogic(question.id, { rules: newRules });
        };

        const handleUpdateRule = (
          ruleIndex: number,
          field: keyof LogicRule,
          value: string,
        ) => {
          const newRules = question.logic.rules.map((r, i) =>
            i === ruleIndex ? { ...r, [field]: value } : r,
          );
          onUpdateLogic(question.id, { rules: newRules });
        };

        return (
          <Card key={question.id}>
            <BlockStack gap="300">
              <InlineStack align="space-between" blockAlign="center">
                <InlineStack gap="200" blockAlign="center">
                  <Badge tone="info">{qIndex + 1}</Badge>
                  <Text as="h3" variant="headingSm" fontWeight="semibold">
                    {question.title || "Untitled question"}
                  </Text>
                  <Badge>{getTypeLabel(question.type)}</Badge>
                </InlineStack>
                <Button size="slim" icon={PlusIcon} onClick={handleAddRule}>
                  Add rule
                </Button>
              </InlineStack>

              {question.logic.rules.length === 0 ? (
                <Box
                  background="bg-surface-secondary"
                  borderRadius="200"
                  padding="300"
                >
                  <Text as="p" variant="bodySm" tone="subdued">
                    No branching rules. Quiz will follow sequential order after
                    this question.
                  </Text>
                </Box>
              ) : (
                <BlockStack gap="200">
                  {question.logic.rules.map((rule, ruleIndex) => {
                    const answerOptions = question.answers.map((a) => ({
                      label: a.text || `Option ${a.position + 1}`,
                      value: a.id,
                    }));

                    return (
                      <Box
                        key={ruleIndex}
                        background="bg-surface-secondary"
                        borderRadius="200"
                        padding="300"
                        borderWidth="025"
                        borderColor="border"
                      >
                        <InlineStack
                          gap="200"
                          blockAlign="center"
                          wrap={false}
                        >
                          <Text
                            as="span"
                            variant="bodySm"
                            tone="subdued"
                          >
                            If answer is
                          </Text>
                          <Box style={{ flex: 1 }}>
                            <Select
                              label="Answer"
                              labelHidden
                              options={answerOptions}
                              value={rule.answerId}
                              onChange={(v) =>
                                handleUpdateRule(ruleIndex, "answerId", v)
                              }
                            />
                          </Box>
                          <Text
                            as="span"
                            variant="bodySm"
                            tone="subdued"
                          >
                            go to
                          </Text>
                          <Box style={{ flex: 1 }}>
                            <Select
                              label="Go to"
                              labelHidden
                              options={gotoOptions}
                              value={rule.goto}
                              onChange={(v) =>
                                handleUpdateRule(ruleIndex, "goto", v)
                              }
                            />
                          </Box>
                          <Button
                            icon={XIcon}
                            tone="critical"
                            variant="plain"
                            onClick={() => handleDeleteRule(ruleIndex)}
                            accessibilityLabel="Delete rule"
                          />
                        </InlineStack>
                      </Box>
                    );
                  })}
                </BlockStack>
              )}
            </BlockStack>
          </Card>
        );
      })}
    </BlockStack>
  );
}

