export default function QuizBuilder() {
  const loaderData = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigate = useNavigate();
  const submit = useSubmit();

  const {
    quiz,
    questions: initialQuestions,
    designSettings: initialDesign,
    quizSettings: initialSettings,
  } = loaderData;

  // Local state for each tab
  const [questions, setQuestions] = useState<Question[]>(initialQuestions);
  const [selectedQuestionIndex, setSelectedQuestionIndex] = useState(0);
  const [design, setDesign] = useState<DesignSettings>(initialDesign);
  const [quizTitle, setQuizTitle] = useState(quiz.title);
  const [quizDescription, setQuizDescription] = useState(quiz.description);
  const [quizSlug, setQuizSlug] = useState(quiz.slug);
  const [quizType, setQuizType] = useState(quiz.type);
  const [settings, setSettings] = useState<QuizSettings>(initialSettings);
  const [selectedTab, setSelectedTab] = useState(0);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);

  // Show toast on every action result
  useEffect(() => {
    if (!actionData) return;
    if (
      "success" in actionData &&
      actionData.success &&
      "message" in actionData
    ) {
      showToast(String(actionData.message), { duration: 3000 });
    } else if ("error" in actionData && actionData.error) {
      showToast(String(actionData.error), { duration: 4000, isError: true });
    }
  }, [actionData]);

  const tabs = [
    { id: "questions", content: "Questions", panelID: "questions-panel" },
    {
      id: "mapping",
      content: "Product Mapping",
      panelID: "mapping-panel",
    },
    { id: "design", content: "Design", panelID: "design-panel" },
    { id: "settings", content: "Settings", panelID: "settings-panel" },
    { id: "logic", content: "Logic", panelID: "logic-panel" },
  ];

  // ── Save handlers ──────────────────────────────────────────────────────────

  const handleSaveQuestions = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "save-questions");
    formData.set(
      "questions",
      JSON.stringify(
        questions.map((q, qi) => ({
          id: q.id,
          title: q.title,
          description: q.description,
          imageUrl: q.imageUrl,
          type: q.type,
          required: q.required,
          position: qi,
          settings: q.settings,
          logic: q.logic,
          answers: q.answers.map((a, ai) => ({
            text: a.text,
            imageUrl: a.imageUrl,
            score: a.score,
            productTags: a.productTags,
            nextQuestionId: a.nextQuestionId,
            position: ai,
          })),
        })),
      ),
    );
    submit(formData, { method: "POST" });
  }, [questions, submit]);

  const handleSaveDesign = useCallback(() => {
    const stylingObj = {
      primaryColor: design.primaryColor,
      buttonTextColor: design.buttonTextColor,
      buttonText: design.buttonText,
      fontFamily: design.fontFamily,
      borderRadius: design.borderRadius,
      showProgressBar: design.showProgressBar,
      progressBarStyle: design.progressBarStyle,
      showQuestionCount: design.showQuestionCount,
      resultsHeading: design.resultsHeading,
    };
    const formData = new FormData();
    formData.set("intent", "save-design");
    formData.set("title", quizTitle);
    formData.set("description", quizDescription);
    formData.set("styling", JSON.stringify(stylingObj));
    submit(formData, { method: "POST" });
  }, [design, quizTitle, quizDescription, submit]);

  const handleSaveSettings = useCallback(() => {
    const settingsObj = {
      requireEmail: settings.requireEmail,
      emailConsentText: settings.emailConsentText,
      showProgressBar: settings.showProgressBar,
    };
    const formData = new FormData();
    formData.set("intent", "save-settings");
    formData.set("title", quizTitle);
    formData.set("description", quizDescription);
    formData.set("slug", quizSlug);
    formData.set("type", quizType);
    formData.set("settings", JSON.stringify(settingsObj));
    submit(formData, { method: "POST" });
  }, [settings, quizTitle, quizDescription, quizSlug, quizType, submit]);

  const handleSaveLogic = useCallback(() => {
    const logicMap: Record<string, QuestionLogic> = {};
    for (const q of questions) {
      logicMap[q.id] = q.logic;
    }
    const formData = new FormData();
    formData.set("intent", "save-logic");
    formData.set("logic", JSON.stringify(logicMap));
    submit(formData, { method: "POST" });
  }, [questions, submit]);

  const handleSave = useCallback(() => {
    switch (selectedTab) {
      case 0:
      case 1:
        handleSaveQuestions();
        break;
      case 2:
        handleSaveDesign();
        break;
      case 3:
        handleSaveSettings();
        break;
      case 4:
        handleSaveLogic();
        break;
      default:
        handleSaveQuestions();
    }
  }, [
    selectedTab,
    handleSaveQuestions,
    handleSaveDesign,
    handleSaveSettings,
    handleSaveLogic,
  ]);

  const handlePublish = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "publish");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handleUnpublish = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "unpublish");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handleDeleteConfirm = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "delete");
    submit(formData, { method: "POST" });
  }, [submit]);

  // ── Question handlers ──────────────────────────────────────────────────────

  const handleSelectQuestion = useCallback((index: number) => {
    setSelectedQuestionIndex(index);
  }, []);

  const handleUpdateField = useCallback(
    (
      field: keyof Question,
      value: string | boolean | QuestionSettings | QuestionLogic,
    ) => {
      setQuestions((prev) => {
        const updated = [...prev];
        updated[selectedQuestionIndex] = {
          ...updated[selectedQuestionIndex],
          [field]: value,
        };
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleUpdateSettings = useCallback(
    (s: QuestionSettings) => {
      setQuestions((prev) => {
        const updated = [...prev];
        updated[selectedQuestionIndex] = {
          ...updated[selectedQuestionIndex],
          settings: s,
        };
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleAddQuestion = useCallback(() => {
    const newQ = makeNewQuestion(questions.length);
    setQuestions((prev) => [...prev, newQ]);
    setSelectedQuestionIndex(questions.length);
  }, [questions.length]);

  const handleDeleteQuestion = useCallback(
    (index: number) => {
      setQuestions((prev) => prev.filter((_, i) => i !== index));
      setSelectedQuestionIndex((prev) =>
        prev >= index && prev > 0 ? prev - 1 : 0,
      );
    },
    [],
  );

  // ── Answer handlers ────────────────────────────────────────────────────────

  const handleUpdateAnswer = useCallback(
    (
      answerId: string,
      field: keyof AnswerOption,
      value: string | number | string[],
    ) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.answers = question.answers.map((a) =>
          a.id === answerId ? { ...a, [field]: value } : a,
        );
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleAddAnswer = useCallback(() => {
    setQuestions((prev) => {
      const updated = [...prev];
      const question = { ...updated[selectedQuestionIndex] };
      question.answers = [
        ...question.answers,
        makeNewAnswer(question.answers.length, question.id),
      ];
      updated[selectedQuestionIndex] = question;
      return updated;
    });
  }, [selectedQuestionIndex]);

  const handleDeleteAnswer = useCallback(
    (answerId: string) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.answers = question.answers.filter((a) => a.id !== answerId);
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleUpdateAnswerTags = useCallback(
    (answerId: string, tags: string[]) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.answers = question.answers.map((a) =>
          a.id === answerId ? { ...a, productTags: tags } : a,
        );
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  // ── Product mapping tag handlers ───────────────────────────────────────────

  const handleAddTag = useCallback(
    (questionId: string, answerId: string, tag: string) => {
      setQuestions((prev) =>
        prev.map((q) =>
          q.id === questionId
            ? {
                ...q,
                answers: q.answers.map((a) =>
                  a.id === answerId
                    ? { ...a, productTags: [...a.productTags, tag] }
                    : a,
                ),
              }
            : q,
        ),
      );
    },
    [],
  );

  const handleRemoveTag = useCallback(
    (questionId: string, answerId: string, tag: string) => {
      setQuestions((prev) =>
        prev.map((q) =>
          q.id === questionId
            ? {
                ...q,
                answers: q.answers.map((a) =>
                  a.id === answerId
                    ? {
                        ...a,
                        productTags: a.productTags.filter((t) => t !== tag),
                      }
                    : a,
                ),
              }
            : q,
        ),
      );
    },
    [],
  );

  // ── Logic handler ──────────────────────────────────────────────────────────

  const handleUpdateLogic = useCallback(
    (questionId: string, logic: QuestionLogic) => {
      setQuestions((prev) =>
        prev.map((q) => (q.id === questionId ? { ...q, logic } : q)),
      );
    },
    [],
  );

  // ── Status helpers ─────────────────────────────────────────────────────────

  const isLive = quiz.status === "active";
  const statusTone = isLive ? "success" : "attention";
  const statusLabel = isLive ? "Live" : "Draft";

  // ==========================================================================
  // RENDER
  // ==========================================================================

  return (
    <>
      <Page
        title={quizTitle || quiz.title}
        backAction={{
          content: "Quizzes",
          onAction: () => navigate("/app/quizzes"),
        }}
        titleMetadata={<Badge tone={statusTone}>{statusLabel}</Badge>}
        primaryAction={{
          content: "Save",
          icon: SaveIcon,
          onAction: handleSave,
        }}
        secondaryActions={[
          {
            content: "Preview",
            icon: EyeFirstIcon,
            onAction: () => navigate(`/app/quizzes/${quiz.id}/preview`),
          },
          isLive
            ? { content: "Unpublish", onAction: handleUnpublish }
            : { content: "Publish", onAction: handlePublish },
          {
            content: "Delete quiz",
            destructive: true,
            icon: DeleteIcon,
            onAction: () => setDeleteModalOpen(true),
          },
        ]}
      >
        <BlockStack gap="400">
          <Card padding="0">
            <Tabs
              tabs={tabs}
              selected={selectedTab}
              onSelect={setSelectedTab}
              fitted
            >
              <Box padding="400">
                {/* Tab 0 — Questions */}
                {selectedTab === 0 && (
                  <QuestionsTab
                    questions={questions}
                    selectedQuestionIndex={selectedQuestionIndex}
                    onSelectQuestion={handleSelectQuestion}
                    onUpdateField={handleUpdateField}
                    onUpdateSettings={handleUpdateSettings}
                    onUpdateAnswer={handleUpdateAnswer}
                    onAddAnswer={handleAddAnswer}
                    onDeleteAnswer={handleDeleteAnswer}
                    onUpdateAnswerTags={handleUpdateAnswerTags}
                    onAddQuestion={handleAddQuestion}
                    onDeleteQuestion={handleDeleteQuestion}
                  />
                )}

                {/* Tab 1 — Product Mapping */}
                {selectedTab === 1 && (
                  <ProductMappingTab
                    questions={questions}
                    onAddTag={handleAddTag}
                    onRemoveTag={handleRemoveTag}
                  />
                )}

                {/* Tab 2 — Design */}
                {selectedTab === 2 && (
                  <DesignTab
                    design={design}
                    quizTitle={quizTitle}
                    quizDescription={quizDescription}
                    onUpdateDesign={(field, value) =>
                      setDesign((prev) => ({ ...prev, [field]: value }))
                    }
                    onUpdateTitle={setQuizTitle}
                    onUpdateDescription={setQuizDescription}
                  />
                )}

                {/* Tab 3 — Settings */}
                {selectedTab === 3 && (
                  <SettingsTab
                    quiz={quiz}
                    quizTitle={quizTitle}
                    quizDescription={quizDescription}
                    quizSlug={quizSlug}
                    quizType={quizType}
                    settings={settings}
                    onUpdateTitle={setQuizTitle}
                    onUpdateDescription={setQuizDescription}
                    onUpdateSlug={setQuizSlug}
                    onUpdateType={setQuizType}
                    onUpdateSettings={setSettings}
                  />
                )}

                {/* Tab 4 — Logic */}
                {selectedTab === 4 && (
                  <LogicTab
                    questions={questions}
                    onUpdateLogic={handleUpdateLogic}
                  />
                )}
              </Box>
            </Tabs>
          </Card>
        </BlockStack>
      </Page>

      {/* Delete confirmation modal */}
      <Modal
        open={deleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        title="Delete quiz?"
        primaryAction={{
          content: "Delete",
          destructive: true,
          onAction: handleDeleteConfirm,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => setDeleteModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="200">
            <Text as="p" variant="bodyMd">
              Are you sure you want to delete{" "}
              <strong>{quizTitle || quiz.title}</strong>?
            </Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              This will permanently delete the quiz, all its questions, answers,
              and response data. This action cannot be undone.
            </Text>
          </BlockStack>
        </Modal.Section>
      </Modal>
    </>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

